{"implementation":"def solve(case):
    import math

    def invalid():
        raise ValueError("invalid or infeasible case")

    if not isinstance(case, dict):
        invalid()
    if "nodes" not in case or "required_symbols" not in case:
        invalid()
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        invalid()
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        invalid()

    required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    by_id = {}
    for node in nodes:
        if not isinstance(node, dict) or any(k not in node for k in required_fields):
            invalid()
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            invalid()
        if parent is not None and not isinstance(parent, str):
            invalid()
        if not isinstance(symbol, str):
            invalid()
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            invalid()
        if not isinstance(removable, bool):
            invalid()
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            invalid()
        by_id[node_id] = node

    roots = [n for n in nodes if n["parent"] is None]
    if len(roots) != 1:
        invalid()
    for node in nodes:
        parent = node["parent"]
        if parent is not None and parent not in by_id:
            invalid()

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])

    root = roots[0]
    if root["depth"] != 0:
        invalid()
    seen = set()
    stack = [(root["id"], 0)]
    while stack:
        node_id, expected_depth = stack.pop()
        if node_id in seen or by_id[node_id]["depth"] != expected_depth:
            invalid()
        seen.add(node_id)
        for child_id in children[node_id]:
            stack.append((child_id, expected_depth + 1))
    if len(seen) != len(nodes):
        invalid()

    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required_symbols):
        invalid()

    active = set(by_id)
    removed = []
    candidates = sorted(
        (node for node in nodes if node["removable"]),
        key=lambda node: (-node["depth"], node["id"]),
    )
    for node in candidates:
        node_id = node["id"]
        if node_id not in active:
            continue
        if node_id == root["id"]:
            continue
        if any(child_id in active for child_id in children[node_id]):
            continue
        if node["symbol"] in symbol_counts and symbol_counts[node["symbol"]] <= 0:
            invalid()
        if node["symbol"] in required_symbols and symbol_counts[node["symbol"]] <= 1:
            continue
        active.remove(node_id)
        symbol_counts[node["symbol"]] -= 1
        removed.append(node_id)

    retained = sorted(active)
    return {"removed_node_ids": removed, "retained_node_ids": retained}"}
